shell('timeline.html','Application timeline',heading('APPLICATION / DEMO-APPLICATION-01','Here’s where things stand.','See the source, the next action and who owns it. Payment does not mean cover is active.')+f'''
<div class="two-column"><section class="document"><div class="section-head"><h2>Awaiting insurer review</h2><span class="chip">Simulated</span></div><ol class="timeline"><li class="complete"><span class="timeline-dot">1</span><div><h3>Mock payment confirmed</h3><p>Original payment retained; onboarding unlocked.</p><p class="fine">Source: application simulator · timestamp not supplied</p></div></li><li class="complete"><span class="timeline-dot">2</span><div><h3>Onboarding and proposal submitted</h3><p>Exact reviewed answer and quote revisions retained.</p><a href="repricing.html">Review a detail change and adjustment ↗</a><p class="fine">Source: payment simulator · timestamp not supplied</p></div></li><li class="active"><span class="timeline-dot">3</span><div><h3>Information requested</h3><p>A document request would state the purpose, recipient and acceptable format.</p><p class="fine">Owner: buyer · request source and date required</p><a href="proposal.html">Review the information request ↗</a></div></li><li><span class="timeline-dot">4</span><div><h3>Insurer decision and issuance</h3><p>Pending. No active-cover claim is shown.</p></div></li></ol></section><aside class="sticky-panel"><p class="eyebrow">NEXT ACTION</p><h2>Review the request.</h2><p>Check whether the information was already supplied. Duplicate or out-of-order updates must not replace newer evidence.</p>{a('help.html','Ask about this request','button secondary')}<hr><h3>More states</h3>{a('state-stale.html','Delayed or stale update','text-link')}{a('policy.html','Preview issued-record layout →','text-link')}</aside></div>
''','SCR-008',[5,34,35],5,True)

shell('policy.html','Policy record and help',heading('POLICY / SIMULATED RECORD','Keep the evidence close.','A policy record must distinguish issuance evidence from effective-cover details.')+f'''
<div class="two-column"><article class="document"><div class="document-head"><span class="chip">Simulated issued record</span><h2>Example policy</h2><p>No real insurance contract</p></div><dl class="definition-list"><div><dt>Issuance reference</dt><dd>SIM-ISSUANCE-01</dd></div><div><dt>Controlling policy document</dt><dd>Not supplied</dd></div><div><dt>Effective-cover start / end</dt><dd>Not supplied — no active-cover claim</dd></div><div><dt>Insurer / source</dt><dd>Not connected</dd></div><div><dt>Renewal terms</dt><dd>Source required</dd></div></dl><button disabled>Download real policy</button><p class="hint">Unavailable in this wireframe.</p></article><aside class="sticky-panel"><h2>Need help with the policy?</h2><p>Find the next step without losing the current record.</p>{a('help.html','Open policy help')}{a('timeline.html','View application history','text-link')}<hr><h3>Before a claim</h3><p>Use the insurer’s exact process and policy wording. The marketplace’s support role must be stated clearly.</p></aside></div>
''','SCR-009/POLICY',[5,36],5,True)

shell('help.html','Help and claim support',heading('HELP / ONE CLEAR NEXT STEP','Let’s make the next step clear.','The marketplace can help organize a request. The insurer decides coverage and claims under the actual policy.')+f'''
<div class="question-grid"><section class="paper-panel"><h2>What do you need help with?</h2><label for="help-topic">Request type</label><select id="help-topic"><option>Application status</option><option>Disclosure wording</option><option>Payment outcome</option><option>Policy document</option><option>Claim assistance process</option></select><label for="help-message">Your question</label><textarea id="help-message" rows="4" placeholder="Use a fictional question for this preview. Do not include policy numbers or medical details."></textarea>{a('help-request.html','Preview a recorded help request')}<p class="hint">No message is sent from the wireframe.</p></section><aside class="paper-panel"><p class="eyebrow">WHO DOES WHAT</p><h2>Clear responsibilities.</h2><dl class="definition-list"><div><dt>Marketplace support</dt><dd>Clarifies the process and tracks the request.</dd></div><div><dt>Insurer</dt><dd>Provides policy decisions, coverage interpretation and claim outcomes.</dd></div><div><dt>Escalation</dt><dd>Verified channel, owner and response expectation must be supplied before launch.</dd></div></dl><a href="timeline.html">Return to current status ↗</a></aside></div>
''','SCR-009/HELP',[5,36],5,True)

shell('help-request.html','Recorded help request',heading('HELP / SIMULATED REQUEST','Your question has a place.','This screen demonstrates a recorded request; no message was sent.')+notice('DEMO-HELP-01 · Awaiting support','The record preserves the question, responsible party, source and next action. No response-time promise is invented.','blue')+'''<dl class="definition-list"><div><dt>Question</dt><dd>Explain the current application step.</dd></div><div><dt>Owner</dt><dd>Support role — staffing not configured</dd></div><div><dt>Last update</dt><dd>Timestamp field · not supplied</dd></div><div><dt>Next action</dt><dd>Support reviews the request and records its response.</dd></div></dl><div class="actions"><a class="button" href="timeline.html">Back to application</a><a class="button secondary" href="help.html">Edit the example question</a></div>''','SCR-009/HELP-RECORDED',[5,36],5,True)

states=[
('loading','Loading the examples.','Keep the layout steady while results arrive.','The final interface announces loading politely, keeps navigation available and avoids showing an empty state before the request resolves.','health.html','View loaded examples','SCR-003/LOADING'),
('empty','No examples match these filters.','Your shortlist is still here.','Reset the filters or broaden the question. An empty result is different from a service failure.','health.html','Reset filters','SCR-003/EMPTY'),
('validation','Check this answer before continuing.','Choose an answer or keep it unresolved.','Associate each error with its field and move focus to this summary. “I am unsure” must never become “No” automatically.','proposal.html','Return to the disclosure','SCR-006/VALIDATION'),
('service-error','We couldn’t load the latest information.','Your choices have been preserved.','Retry the same read. Do not replace unknown terms with an assumption or discard the current shortlist.','health.html','Try the example again','SCR-003/SERVICE-ERROR'),
('stale','There’s a newer version to review.','Your saved version has not been replaced.','Show the previous and current source revisions. An expired or changed offer needs a fresh review before acceptance or payment.','revised-offer.html','Review the change','SCR-007/STALE'),
('save-failed','This summary hasn’t been saved yet.','Keep this page open while you retry.','The current selections remain visible. Do not report success until the save has a confirmed result.','summary.html','Return to your selections','SCR-005/SAVE-FAILED'),
('session-expired','Sign in again to continue.','Your account needs a new session.','Keep a safe draft where permitted. After authentication, return to this step and recheck ownership and the current version.','proposal.html','Preview resumed draft','SCR-006/SESSION-EXPIRED'),
('permission','This record isn’t available to you.','Check the account you are using.','Do not reveal another buyer’s identity, policy or application details. Support can help resolve access without exposing the record.','help.html','Get help with access','SCR-009/PERMISSION'),
('conflict','This draft changed while you were reviewing.','Review the current revision before submitting.','Preserve the buyer’s draft and explain the conflict. Do not silently overwrite another edit or submit a revision the buyer has not reviewed.','review.html','Review current revision','SCR-006/CONFLICT')]
