    shell('state-'+slug+'.html',title,heading('RECOVERY / '+slug.replace('-',' ').upper(),title)+f'<section class="state-panel"><div class="state-mark" aria-hidden="true">'+('…' if slug=='loading' else '!')+f'</div><h2>{short}</h2><p>{user_copy}</p>{extra}<div class="actions">{a(target,label)}{a("flow.html","All states","button secondary")}</div></section><details class="review-annotation"><summary>Design notes for this state</summary><p>{body}</p></details>',scr,[49],4,True,slug)

